-- Execute the exact wrapper generated by compile_strategy, then change state at the policy entry.
local strategy = arg[1]
local scenario = arg[2] or "entry"
local actions, snapshots = 0, 0
local initial_state = {
    ready = true,
    instance_id = "current-instance",
    scene_generation = 2,
    map_id = 100,
    character = { id = 4, hp = 100, max_hp = 100, level = 3, experience = 0, mp = 20, max_mp = 30 },
    position = { x = 10, y = 20 },
    inventory = { { item_id = 2000000, quantity = 1 } },
    monsters = {},
}
local changed_state = {
    ready = true,
    instance_id = "replacement-instance",
    scene_generation = 3,
    map_id = 200,
    character = { id = 5, hp = 0, max_hp = 100, level = 3, experience = 0, mp = 20, max_mp = 30 },
    position = { x = 10, y = 20 },
    inventory = { { item_id = 2000000, quantity = 1 } },
    monsters = {},
}
local change_at = 2
if scenario:sub(1, 10) == "preflight-" then
    change_at = 1
    changed_state.instance_id = initial_state.instance_id
    changed_state.scene_generation = initial_state.scene_generation
    changed_state.map_id = initial_state.map_id
    changed_state.character = initial_state.character
    if scenario == "preflight-instance" then
        changed_state.instance_id = "replacement-instance"
    elseif scenario == "preflight-character" then
        changed_state.character = { id = 5, hp = 100, max_hp = 100, level = 3, experience = 0, mp = 20, max_mp = 30 }
    elseif scenario == "preflight-map" then
        changed_state.map_id = 200
    elseif scenario == "preflight-generation" then
        changed_state.scene_generation = 3
    else
        error("unknown scenario: " .. scenario)
    end
end
game = {
    state = function()
        snapshots = snapshots + 1
        return snapshots < change_at and initial_state or changed_state
    end,
    time = function() return 0 end,
    sleep = function() end,
    log = function() end,
    move = function() actions = actions + 1 end,
    attack = function() actions = actions + 1 end,
    use_item = function() actions = actions + 1 end,
}
local handle = assert(io.open(strategy, "r"))
local source = handle:read("*a")
handle:close()
local chunk = assert(load(source, "@compiled-strategy-context-contract"))
local ok, failure = pcall(chunk)
assert(not ok and tostring(failure):find("strategy_scene_context_stale"), tostring(failure))
assert(snapshots == change_at, "generated preflight or strategy entry sampled an unexpected number of states")
assert(actions == 0, "stale scene context dispatched a game action")
